package fpv.render;
import arc.*;import arc.graphics.*;import arc.graphics.g2d.*;import arc.mock.*;import arc.util.*;import mindustry.*;import mindustry.content.*;import mindustry.core.*;import mindustry.game.*;import mindustry.gen.*;import mindustry.world.*;import mindustry.world.blocks.defense.*;import mindustry.world.blocks.storage.*;import fpv.construction.*;import java.util.*;
public final class SupportModelNativeTest {
 static int checks;static void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}static class Tex extends Texture{Tex(){super();width=height=64;}}
 static Block[] types(){return new Block[]{Blocks.mender,Blocks.mendProjector,Blocks.overdriveProjector,Blocks.overdriveDome,Blocks.forceProjector,Blocks.container,Blocks.vault,Blocks.regenProjector,Blocks.buildTower,Blocks.reinforcedContainer,Blocks.reinforcedVault};}
 static void pose(Building b,float amount){b.enabled=amount>0;b.efficiency=amount;b.optionalEfficiency=amount*.5f;
  if(b instanceof MendProjector.MendBuild v){v.heat=v.smoothEfficiency=amount;v.charge=((MendProjector)b.block).reload*amount;v.phaseHeat=amount*.5f;}
  if(b instanceof OverdriveProjector.OverdriveBuild v){v.heat=v.smoothEfficiency=amount;v.charge=((OverdriveProjector)b.block).reload*amount;v.phaseHeat=amount*.5f;}
  if(b instanceof ForceProjector.ForceBuild v){v.broken=amount==0;v.warmup=v.radscl=amount;v.buildup=((ForceProjector)b.block).shieldHealth*(1-amount);v.hit=amount*.3f;}
  if(b instanceof RegenProjector.RegenProjectorBuild v){v.anyTargets=v.didRegen=amount>0;v.warmup=amount;v.totalTime=19*amount;}
  if(b instanceof BuildTurret.BuildTurretBuild v){v.lastPlan=amount>0?new Teams.BlockPlan(10,10,(short)0,Blocks.container,null):null;v.warmup=amount;v.rotation=37;v.unit.rotation(37);}
  if(b instanceof StorageBlock.StorageBuild){b.items.clear();b.items.set(Items.copper,(int)(b.getMaximumAccepted(Items.copper)*amount));}
 }
 public static void main(String[] args)throws Exception{
  ArcNativesLoader.load();mindustry.graphics.CacheLayer.init();Core.app=new MockApplication();Core.files=new MockFiles();Core.settings=new MockSettings();Core.bundle=I18NBundle.createEmptyBundle();Core.audio=new MockAudio();Core.graphics=new MockGraphics();Core.gl=new MockGL20();Vars.headless=true;Vars.tree=new FileTree();Vars.content=new ContentLoader();Vars.content.createBaseContent();Vars.state=new GameState();Vars.net=new mindustry.net.Net(null);Groups.init();Vars.world=new World();Vars.world.tiles=new Tiles(128,96);Vars.world.setGenerating(true);Vars.world.tiles.fill();Vars.indexer=new mindustry.ai.BlockIndexer();Groups.resize(0,0,1024,768);Time.clear();Time.setDeltaProvider(()->1);Vars.content.init();Vars.state.set(GameState.State.playing);
  var pix=new Pixmap(32,32);pix.fill(0xa0a0a0ff);var region=new TextureAtlas.AtlasRegion(new Tex(),0,0,32,32);region.name="chemical-fixture";Core.atlas=new TextureAtlas(){@Override public PixmapRegion getPixmap(TextureAtlas.AtlasRegion a){return new PixmapRegion(pix);}};Core.atlas.addRegion("white",region);


  Block[] types=types();int[] sizes={1,2,2,3,3,2,3,3,3,2,3};check(!SupportModelRenderer.supports(Blocks.shieldProjector)&&!SupportModelRenderer.supports(Blocks.largeShieldProjector)&&!SupportModelRenderer.supports(Blocks.shieldBreaker)&&SupportModelRenderer.supports(Blocks.forceProjector),"scoped playable models; campaign barrier semantics untouched");
  for(int i=0;i<types.length;i++){var b=types[i];check(b.size==sizes[i],"installed footprint "+b.name);b.region=b.fullIcon=region;if(b instanceof MendProjector v)v.topRegion=region;if(b instanceof OverdriveProjector v)v.topRegion=region;if(b instanceof ForceProjector v)v.topRegion=region;if(b instanceof BuildTurret v)v.baseRegion=region;System.out.println("A2-16i native "+b.name+" size="+b.size+" capacity="+b.itemCapacity+" height="+fpv.net.HeadlessGeometry.heightFor(b)+" class="+b.buildType.get().getClass().getName());}
  for(Block b:new Block[]{Blocks.shieldProjector,Blocks.largeShieldProjector,Blocks.shieldBreaker}){if(b==null){System.out.println("A2-16i optional audit shieldBreaker declared but unregistered/null in installed160.7");continue;}String visibility="custom";for(var field:mindustry.world.meta.BuildVisibility.class.getFields())if(field.getType()==mindustry.world.meta.BuildVisibility.class&&field.get(null)==b.buildVisibility)visibility=field.getName();System.out.println("A2-16i optional audit "+b.name+" class="+b.buildType.get().getClass().getName()+" visibility="+visibility+" editor="+b.inEditor+" layerSupported="+LayerBuildingAdapter.supports(b));}
  for(var p:SupportModelProfile.values())for(int lod=0;lod<3;lod++){var g=SupportModelGeometry.model(p,sizes[p.ordinal()],lod);check(g==SupportModelGeometry.model(p,sizes[p.ordinal()],lod),"cached templates");int count=0;for(var a:new float[][]{g.body(),g.lining(),g.moving(),g.lights(),g.booster()}){count+=a.length/8;check(a.length%24==0,"triangles");for(int i=0;i<a.length;i+=8){for(int j=0;j<8;j++)check(Float.isFinite(a[i+j]),"finite native mesh");check(Math.abs(a[i])<=.501&&Math.abs(a[i+2])<=.501&&a[i+1]>=0&&a[i+1]<=1,"bounded model");}}check(count<3000,"bounded complexity");}
  var renderer=new SupportModelRenderer();var batch=new NativeAtlasMesh.Builder(false);long id=100;
  try{
   for(int floor:new int[]{0,1,3,4,5})for(int t=0;t<types.length;t++)for(int rotation=0;rotation<4;rotation++){
    var b=AdvancedLogisticsNativeTest.put(new LayerBuildingAdapter(null),id++,12+rotation*24,10+t*5,floor,types[t],rotation);
    for(float amount:new float[]{0,.5f,1}){pose(b,amount);float level=SupportModelRenderer.level(b),phase=SupportModelRenderer.phase(b);if(b instanceof StorageBlock.StorageBuild)check(Math.abs(level-amount)<.005,"real per-item native capacity, no aggregate invented denominator");else check(amount==0?level==0:level>0,"actual active/idle/readiness state");Time.time+=200;check(phase==SupportModelRenderer.phase(b),"native phase independent of render time");
     for(float distance:new float[]{0,900,10000}){var before=LogisticsModelNativeTest.state(b);float h=fpv.net.HeadlessGeometry.heightFor(b.block),base=floor*1.4f;batch.clear();check(renderer.render(b,batch,0,base,0,b.block.size,h,distance),"all native XYZ/rotations/LOD");var vertices=LogisticsModelNativeTest.vertices(batch);for(int i=0;i<vertices.length;i+=9){for(int j=0;j<9;j++)check(Float.isFinite(vertices[i+j]),"finite transformed native stream");check(Math.abs(vertices[i])<=b.block.size*.501&&Math.abs(vertices[i+2])<=b.block.size*.501&&vertices[i+1]>=base-.001&&vertices[i+1]<=base+h+.01,"inside unchanged physical envelope");check(vertices[i+7]>=0&&vertices[i+7]<=.5&&vertices[i+8]>=0&&vertices[i+8]<=.5,"atlas UV bounds");}check(Arrays.equals(before,LogisticsModelNativeTest.state(b))&&level==SupportModelRenderer.level(b)&&phase==SupportModelRenderer.phase(b),"no native inventory/repair/shield/boost/build-state mutation");}
    }
    if(b instanceof RegenProjector.RegenProjectorBuild v){v.enabled=true;v.efficiency=1;v.warmup=1;v.anyTargets=true;v.didRegen=false;check(SupportModelRenderer.level(v)==0,"no invented regen animation without native repair target flags");}
    if(b instanceof BuildTurret.BuildTurretBuild v){v.enabled=true;v.efficiency=1;v.warmup=1;v.lastPlan=null;v.following=null;check(SupportModelRenderer.level(v)==0,"no fictitious construction work");}
   }
   var store=(StorageBlock.StorageBuild)AdvancedLogisticsNativeTest.put(new LayerBuildingAdapter(null),id++,18,80,0,Blocks.container,0);Vars.world.tile(100,80).setBlock(Blocks.coreShard,Team.sharded,0);var core=Vars.world.build(100,80);store.linkedCore=core;store.items=core.items;store.items.clear();int cap=store.getMaximumAccepted(Items.copper);store.items.set(Items.copper,cap/2);check(Math.abs(SupportModelRenderer.fullness(store)-.5f)<.01,"linked-core inventory uses native accepted capacity");
   var behavior=new LayerBuildingAdapter(null);var repair=(MendProjector.MendBuild)behavior.create(id++,20,84,12,Blocks.mendProjector,Team.sharded,0);var target=behavior.create(id++,24,84,12,Blocks.mechanicalDrill,Team.sharded,0);target.health=target.maxHealth*.5f;float beforeHealth=target.health;repair.efficiency=1;repair.power.status=1;for(int n=0;n<400;n++){Time.delta=1;repair.updateTile();}check(target.health>beforeHealth,"native upper mend actually heals with unchanged rules");
   var over=(OverdriveProjector.OverdriveBuild)behavior.create(id++,20,78,12,Blocks.overdriveProjector,Team.sharded,0);over.efficiency=1;over.heat=1;over.charge=((OverdriveProjector)over.block).reload;over.updateTile();check(target.timeScale()>1,"native acceleration really boosts an eligible actual building");
   var regen=(RegenProjector.RegenProjectorBuild)behavior.create(id++,24,78,12,Blocks.regenProjector,Team.sharded,0);target.health=target.maxHealth*.5f;beforeHealth=target.health;regen.efficiency=1;regen.updateTile();check(target.health>beforeHealth&&regen.didRegen,"native regen actually heals before model reports active");regen.anyTargets=regen.didRegen=false;check(SupportModelRenderer.level(regen)==0,"no repair light from warmup alone");behavior.clear();
   check(renderer.entries()==11&&renderer.builds()==11&&renderer.bytes()<2_000_000,"bounded cache reused across instances/state");
   System.out.println("SupportModelNativeTest: "+checks+" installed scope/XYZ/UV/LOD/cache/native readiness/shield/inventory/read-only checks PASS; mock GL, physical acceptance separate");
  }finally{renderer.clear();batch.dispose();pix.dispose();}
 }
}
